import{j as t}from"./compare-pages-C1d7etmC.js";import{I as e}from"./I18nErpPage-ats_sIzh.js";import"./PillarHubNav-4Fa_GMYz.js";import"./badge-Cm4itCyF.js";const i={heroBadge:"نظام إدارة فحوصات الاختبارات غير المتلفة",heroTitle:"برنامج تخطيط موارد المؤسسات للاختبارات غير المتلفة في المملكة العربية السعودية",heroSubtitle:"حل متكامل لإدارة الفحص والتفتيش",heroIntro:"نظام تخطيط موارد متخصص لشركات الاختبارات غير المتلفة العاملة في المملكة العربية السعودية. أتمتة متابعة شهادات الـ ASNT، وجدولة فحوصات API 510 و API 570 و API 653، وإصدار تقارير PDF بصيغة سعودي أرامكو خلال دقائق بدلًا من ساعات.",ctaPrimary:"اطلب عرضًا توضيحيًا للمملكة العربية السعودية",ctaSecondary:"English version",statCompanies:"شركة فحص تستخدم النظام",statRating:"متوسط تقييم العملاء",statAdminReduction:"تقليل الوقت الإداري",statModules:"وحدات رئيسية للاختبارات غير المتلفة",marketContextLabel:"سياق سوق الاختبارات غير المتلفة",painPointsTitle:"لماذا تختار فرق الاختبارات غير المتلفة في المملكة العربية السعودية نظام أتلانتيس؟",painPointsSubtitle:"ثلاث نقاط ألم تشغيلية حرجة يتم القضاء عليها منذ اليوم الأول للنشر",problemLabel:"المشكلة",solutionLabel:"الحل",modulesTitle:"ست وحدات أساسية لشركات الاختبارات غير المتلفة",modulesSubtitle:"كل وحدة مصممة خصيصًا لقطاع التفتيش الصناعي، وليست برنامج أعمال عامًا أعيد تسميته",roiTitle:"العائد على الاستثمار في المملكة العربية السعودية",faqTitle:"الأسئلة الشائعة — نظام تخطيط موارد الاختبارات غير المتلفة في المملكة العربية السعودية",alsoServingTitle:"خدمات أخرى",finalCtaTitle:"هل أنت مستعد لتحديث عمليات الاختبارات غير المتلفة في المملكة العربية السعودية؟",finalCtaBody:"انضم إلى شركات التفتيش في الرياض والدمام وينبع والجبيل التي استبدلت جداول البيانات والسجلات الورقية بنظام أتلانتيس. اطلب عرضًا توضيحيًا مخصصًا لسير عملك في الفحص.",finalCtaPrimary:"اطلب عرضًا توضيحيًا",finalCtaSecondary:"View English version",switchLangLabel:"English version"};function s(){return t.jsx(e,{lang:"ar",dir:"rtl",city:"المملكة العربية السعودية",countryCode:"SA",countryName:"المملكة العربية السعودية",slug:"ndt-erp-saudi-arabia",canonicalPath:"/ar/ndt-erp-saudi-arabia",englishPath:"/ndt-erp-saudi-arabia",pageTitle:"برنامج تخطيط موارد الاختبارات غير المتلفة في المملكة العربية السعودية | أتلانتيس NDT",pageDescription:"برنامج تخطيط موارد للاختبارات غير المتلفة لشركات التفتيش في المملكة العربية السعودية. أتمتة متابعة شهادات ASNT، وجدولة API 510 و API 570 و API 653، وإصدار تقارير PDF متوافقة مع متطلبات سعودي أرامكو ومعايير سابك.",keywords:"برنامج تخطيط موارد الاختبارات غير المتلفة, السعودية, نظام إدارة فحص, ASNT, API 510, API 570, سعودي أرامكو, سابك, شركة فحص الرياض, الدمام, ينبع, الجبيل",marketContext:"تشغّل المملكة العربية السعودية أكبر شبكة متكاملة للنفط والغاز في العالم، حيث تفرض متطلبات التأهيل وفق معيار سعودي أرامكو SAEP-1112 ومتطلبات إدارة سلامة الأصول لدى شركة سابك بيئة تنظيمية صارمة على مزودي خدمات التفتيش. ومن حقول الربع الخالي إلى المجمعات الصناعية الضخمة في ينبع والجبيل ورأس تنورة، تتطلب هذه العمليات أنظمة لإدارة الفحص قادرة على التعامل مع آلاف أوامر العمل المتزامنة. يدعم نظام أتلانتيس لتخطيط موارد الاختبارات غير المتلفة متابعة تأهيل المفتشين المتوافق مع معايير أرامكو، وإصدار تقارير PDF متعددة اللغات، وتتبع الاتجاهات التآكلية في الوقت الفعلي للفرق العاملة داخل المملكة. كما يلبي النظام متطلبات الهيئة السعودية للمواصفات والمقاييس والجودة (ساسو) ومتطلبات سلامة الإجراءات الصادرة عن الهيئة العامة للأرصاد وحماية البيئة، ويوفر سجلات يمكن تدقيقها بسهولة أثناء عمليات المراجعة الفصلية لشركات أرامكو وسابك وأرامكو-توتال للتكرير والبتروكيماويات (ساتورب) ومجمع رابغ للتكرير والبتروكيماويات (بترورابغ).",roiBody:"يبلّغ عملاء نظام أتلانتيس في المملكة العربية السعودية عن تقليل الوقت الإداري بنسبة 40% خلال أول ستة أشهر من النشر، مع انخفاض زمن إعداد تقرير API 510 من أربع ساعات إلى أقل من خمس دقائق. كما تختفي حوادث انتهاء شهادات ASNT دون انتباه نتيجة التنبيهات الآلية قبل 90 و60 و30 يومًا من تاريخ الانتهاء، ويصبح إعداد ملف التدقيق الكامل لمراجعة أرامكو متاحًا بضغطة زر واحدة. بالنسبة لفريق فحص مكوّن من عشرة فنيين في الرياض أو الدمام، يمثل هذا توفيرًا سنويًا يتراوح بين 58,500 و78,000 ريال سعودي في النفقات الإدارية القابلة للاسترداد، قبل احتساب القيمة الوقائية لتجنب فقدان أهلية العقود.",painPoints:[{title:"خطر انتهاء الشهادات",problem:"تواجه شركات الفحص في المملكة العربية السعودية خطر فقدان اعتماد العملاء وأهلية العقود عندما تنتهي شهادات ASNT أو ISO 9712 أو CSWIP دون ملاحظة عبر مجموعات الفنيين الكبيرة العاملة في مشاريع أرامكو وسابك وبترورابغ.",solution:"يتتبع نظام أتلانتيس كل مؤهل تلقائيًا ويرسل تنبيهات بريد إلكتروني قبل 90 و60 و30 يومًا للفنيين والمشرفين، ممّا يلغي الحاجة إلى مراجعات جداول البيانات قبل التعبئة في مواقع ينبع والجبيل."},{title:"إعداد التقارير اليدوي",problem:"تستغرق فرق الفحص في المملكة من ساعتين إلى أربع ساعات في تنسيق كل تقرير وفق API 510 أو API 570 يدويًا، وهو وقت كان يمكن أن يُخصَّص لأعمال فنية ذات قيمة مضافة في المنشآت السعودية.",solution:"أصدر تقريرًا كاملًا بصيغة API ومتوافقًا مع متطلبات سعودي أرامكو SAEP-1142 في أقل من خمس دقائق مباشرةً من البيانات الميدانية، دون إعادة تنسيق أو أخطاء نسخ ولصق."},{title:"صعوبة الاستعداد للتدقيق",problem:"تكشف عمليات تدقيق أرامكو وسابك بشكل متكرر عن شركات تفتيش في المملكة العربية السعودية تفتقر إلى سجلات منظمة وفورية الوصول لتاريخ الفحص ومؤهلات الموظفين، مما يهدد استمرارية اعتمادها كمورّد معتمد.",solution:"يولّد نظام أتلانتيس حزمة تدقيق كاملة — تاريخ فحص الأصول، وسجلات تأهيل الأفراد، وشهادات المعايرة، وحالة الامتثال — بنقرة واحدة في أي وقت قبل زيارة المدققين."}],modules:[{title:"جدولة الفحص وإدارة أوامر العمل",description:"أتمتة احتساب فترات الفحص وفقًا لمعايير API 510 و API 570 و API 653 وفترات الفحص القائم على المخاطر المحددة من العميل. خصص الفنيين والمعدات والإجراءات لأوامر العمل في ثوانٍ.",features:["احتساب تلقائي لفترات API 510/570/653","جدولة الفحص القائم على المخاطر (RBI)","مصفوفة توفر الفنيين","تدفقات اعتماد أوامر العمل","وصول ميداني للمفتشين عبر الهاتف"]},{title:"تتبع شهادات أفراد الاختبارات غير المتلفة",description:"مركز سجلات شهادات ASNT SNT-TC-1A و ISO 9712 و PCN و CSWIP والمؤهلات الخاصة بكل عميل. تلقّ تنبيهات تلقائية قبل 90 و60 و30 يومًا من انتهاء الشهادات.",features:["تنبيهات انتهاء ASNT المستويات الأول والثاني والثالث","متابعة ISO 9712 و PCN و CSWIP","مصفوفة المؤهلات وفق ممارسة العميل المكتوبة","رسائل تذكير تلقائية بالتجديد","تصدير شهادات PDF جاهزة للتدقيق"]},{title:"إصدار تقارير الفحص",description:"أنشئ تقارير فحص احترافية بصيغة PDF وفقًا لمعايير API 510 و API 570 و API 653 و ASME القسم الثامن وصيغ العميل المخصصة مباشرة من بيانات الإدخال الميدانية — دون إعادة تنسيق يدوي.",features:["قوالب تقارير فحص الأوعية الضاغطة API 510","صيغ فحص الأنابيب API 570","تقارير فحص خزانات التخزين API 653","منشئ قوالب مخصصة للعميل","تكامل التوقيع الرقمي والختم"]},{title:"إدارة بيانات التآكل وتتبع الاتجاهات",description:"سجّل قراءات السماكة ومعدلات التآكل وحسابات العمر المتبقي لجميع الأصول. اعرض اتجاهات التدهور بمخططات ملونة واحسب تواريخ الإحالة للتقاعد تلقائيًا.",features:["قاعدة بيانات قياسات السماكة بالموجات فوق الصوتية","مخططات اتجاه معدل التآكل","احتساب العمر المتبقي وتاريخ التقاعد","تنبيهات نسبة فقدان السماكة","تصدير تقييم API 579 لقابلية الخدمة"]},{title:"سجل الأصول وإدارة المعدات",description:"احتفظ بسجل رقمي كامل للأصول يغطي الأوعية الضاغطة ودوائر الأنابيب وخزانات التخزين والمكونات الإنشائية. تتبع حالة معايرة المعدات وأدوات الفحص.",features:["هيكلية أصول مرتبطة بمخططات P&ID","متتبع تواريخ استحقاق معايرة المعدات","وسم الأصول برموز QR والباركود","سجل فحص تاريخي لكل أصل","تصنيف المخاطر ودرجة الأهمية"]},{title:"لوحة الامتثال",description:"رؤية فورية لامتثال معايير API و ASME ومتطلبات العميل والجهات التنظيمية المحلية في المملكة العربية السعودية. لوحة قيادة تنفيذية مع تنبيهات الفحوصات المتأخرة ومتابعة مؤشرات الأداء.",features:["لوحة تنبيه الفحوصات المتأخرة","نظرة عامة على حالة الامتثال متعدد العملاء","تقارير مؤشرات الأداء: التسليم في الوقت المحدد، معدلات حالات عدم المطابقة","تنبيهات تغييرات اللوائح التنظيمية","تقارير ملخص تنفيذي على مستوى مجلس الإدارة"]}],integrations:["متابعة تأهيل سعودي أرامكو SAEP-1112","تقارير بصيغة ساسو SASO","تكامل SAP S/4HANA","توثيق الجودة والصحة والسلامة لشركة سابك (QHSE)","الامتثال لمعايير أرامكو IADC","تكامل بوابة موردي أرامكو","ربط مع نظام إدارة سير العمل في بترورابغ","صيغ تقارير ساتورب SATORP"],faqs:[{question:"هل يدعم النظام متطلبات سعودي أرامكو SAEP-1142 لإعداد تقارير الفحص؟",answer:"نعم. يتضمن نظام أتلانتيس قوالب جاهزة لتقارير API 510 و API 570 و API 653 مع التعديلات اللازمة لاستيفاء متطلبات سعودي أرامكو SAEP-1142 و SAEP-1112 لتأهيل المفتشين. يمكنك تخصيص رأس التقرير ليتضمن شعار شركتك ورقم اعتماد المورد لدى أرامكو، وتُصدَر التقارير بصيغة PDF عالية الجودة جاهزة للتقديم لقسم تكامل الأصول في أرامكو."},{question:"كيف يتعامل النظام مع متطلبات التتبع وفق معيار ساسو؟",answer:"تشمل وحدة الامتثال متابعة كاملة للوثائق وفق معايير الهيئة السعودية للمواصفات والمقاييس والجودة (ساسو)، بما في ذلك معايير IS 2825 للأوعية الضاغطة. يحتفظ النظام بسجل قابل للتدقيق يتضمن تاريخ كل قراءة سماكة، ومعرّف الفني المنفذ، ومرجع الإجراء المعتمد، وحالة معايرة الجهاز المستخدم في وقت القياس."},{question:"هل يدعم النظام تعدد المواقع بين الرياض والدمام وينبع؟",answer:"نعم. يسمح النظام السحابي بإدارة عمليات متعددة المواقع من لوحة قيادة موحدة، مع تقسيم الصلاحيات حسب الموقع والعميل. يمكن لفريق إدارة في الرياض رؤية تقدم العمل في مصافي ينبع والجبيل في الوقت الفعلي، بينما يصل الفنيون الميدانيون فقط إلى أوامر العمل المخصصة لهم."},{question:"هل يعمل التطبيق بدون اتصال بالإنترنت في مواقع العمل النائية؟",answer:"نعم. يتضمن النظام وضع جمع البيانات دون اتصال للعمل في المواقع النائية في الربع الخالي أو المنشآت البحرية في الخليج العربي. تتم المزامنة تلقائيًا عند استعادة الاتصال، مما يضمن عدم فقدان أي بيانات فحص حتى في البيئات التي يكون فيها الاتصال متقطعًا."},{question:"ما هي مدة التنفيذ والترحيل من جداول البيانات؟",answer:"يستغرق التنفيذ النموذجي لشركة فحص في المملكة العربية السعودية من أربعة إلى ستة أسابيع، شاملًا ترحيل البيانات التاريخية وتدريب الفرق وتكامل قوالب التقارير الخاصة بسعودي أرامكو وسابك. يوفر فريق التنفيذ لدينا قوالب استيراد Excel للأصول والمعدات وسجلات الموظفين، ويتولى متخصص تنفيذ مكرّس التحقق من البيانات قبل النشر."}],ui:i})}export{s as default};
